// Keeps Android builds within a small machine's memory (an 8 GB orb or a CI runner).
// android/ is generated by `expo prebuild`, so these settings live here instead of in
// android/gradle.properties, where a clean prebuild would drop them.
const { withGradleProperties } = require('expo/config-plugins');

const SETTINGS = {
  // -Xmx caps only the Java heap: the daemon also uses metaspace, code cache, and native memory,
  // so expect it to reach about 3 GB in total.
  'org.gradle.jvmargs': '-Xmx2g -XX:MaxMetaspaceSize=512m',
  'org.gradle.workers.max': '2',
  'org.gradle.parallel': 'false',
  'kotlin.daemon.jvmargs': '-Xmx1g',
};

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (config) => {
    const keys = new Set(Object.keys(SETTINGS));
    config.modResults = config.modResults.filter(
      (item) => !(item.type === 'property' && keys.has(item.key)),
    );
    for (const [key, value] of Object.entries(SETTINGS)) {
      config.modResults.push({ type: 'property', key, value });
    }
    return config;
  });
};
